const ll INF = 1e14;
const int MAXN = 8200;

struct Edge {
    int u, v;
    ll cap, flow, cost;
    ll rem() { return cap - flow; }
    Edge() {}
    Edge(int _u, int _v, ll _cap, ll _flow, ll _cost) : u(_u), v(_v), cap(_cap), flow(_flow), cost(_cost) {}
};

int nodes;
vector<int> adj[MAXN];
vector<Edge> edges;

void addEdge(int u, int v, ll cap, ll cost) {
    adj[u].push_back(sz(edges));
    edges.push_back(Edge(u, v, cap, 0, cost));
    adj[v].push_back(sz(edges));
    edges.push_back(Edge(v, u, 0, 0, -cost));
}

ll dist[MAXN];
ll minCost;
int pre[MAXN];
ll capacity[MAXN];
ll maxFlow;
ll potential[MAXN];
bool inQueue[MAXN];

void minCostMaxFlow(int s, int t) {
    memset(inQueue, 0, sizeof(inQueue));
    maxFlow = minCost = 0;
    // Initial potentials using Bellman-Ford (SPFA)
    fill(potential, potential + MAXN, INF);
    potential[s] = 0;
    queue<int> q;
    q.push(s);
    inQueue[s] = 1;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        inQueue[u] = 0;
        for (int it = 0; it < sz(adj[u]); ++it) {
            int i = adj[u][it];
            Edge &f = edges[i];
            if (f.rem() && potential[f.v] > potential[u] + f.cost + 1e-9) {
                potential[f.v] = potential[u] + f.cost;
                if (!inQueue[f.v]) {
                    q.push(f.v);
                    inQueue[f.v] = 1;
                }
            }
        }
    }
    // Now potentials are set, use Dijkstra with reduced costs
    while (true) {
        fill(dist, dist + nodes, INF);
        dist[s] = 0;
        memset(pre, -1, sizeof(pre));
        pre[s] = 0;
        memset(capacity, 0, sizeof(capacity));
        capacity[s] = INF;
        priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
        pq.push({0, s});
        while (!pq.empty()) {
            auto [d, u] = pq.top();
            pq.pop();
            if (d != dist[u]) continue;
            for (int it = 0; it < sz(adj[u]); ++it) {
                int i = adj[u][it];
                Edge &f = edges[i];
                ll reduced = f.cost + potential[u] - potential[f.v];
                if (f.rem() && dist[f.v] > dist[u] + reduced + 1e-9) {
                    dist[f.v] = dist[u] + reduced;
                    pre[f.v] = i;
                    capacity[f.v] = min(capacity[u], f.rem());
                    pq.push({dist[f.v], f.v});
                }
            }
        }
        if (pre[t] < 0) break;
        // Update potentials
        for (int v = 0; v < nodes; ++v) {
            if (dist[v] < INF) potential[v] += dist[v];
        }
        maxFlow += capacity[t];
        minCost += capacity[t] * potential[t]; // potential[t] now equals original distance
        int v = t;
        while (v != s) {
            edges[pre[v]].flow += capacity[t];
            edges[pre[v] ^ 1].flow -= capacity[t];
            v = edges[pre[v]].u;
        }
    }
